const { memo, useState } = React;

const BuyButton = memo(function BuyButton({ onBuy }) {
  console.log('BuyButton 렌더');
  return <button type="button" onClick={onBuy}>구매</button>;
});

function App() {
  const [name, setName] = useState('');
  function handleBuy() { console.log('구매'); }

  return (
    <main>
      <input value={name} onChange={(event) => setName(event.currentTarget.value)} placeholder="이름" />
      <BuyButton onBuy={handleBuy} />
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

